return-response.set-body:
@{
                var caller = (Jwt)context.Variables["caller-jwt"];
                var obo = ((string)context.Variables["obo-token"]).AsJwt();
                var me = (IResponse)context.Variables["me"];
                var body = me.Body.As();
                return new JObject(
                    new JProperty("caller_oid", caller.Claims.GetValueOrDefault("oid", "")),
                    new JProperty("obo_oid", obo.Claims.GetValueOrDefault("oid", "")),
                    new JProperty("obo_aud", string.Join(",", obo.Audiences)),
                    new JProperty("obo_scp", obo.Claims.GetValueOrDefault("scp", "")),
                    new JProperty("databricks_status", me.StatusCode),
                    new JProperty("databricks_user", body["userName"] ?? body["message"])).ToString();
            }
